import java.util.Scanner;

public class Main {
    static final int MOD = 1000000007;
    static final int DIM = 32;
    static final int MAX_D = 64;
    static final int MAX_K = 32;

    static class Matrix {
        int[][] m = new int[DIM][DIM];

        Matrix() {
            for (int i = 0; i < DIM; i++) {
                for (int j = 0; j < DIM; j++) {
                    m[i][j] = 0;
                }
            }
        }

        int[] getRow(int i) {
            return m[i];
        }

        static Matrix multiply(Matrix A, Matrix B) {
            Matrix R = new Matrix();
            for (int i = 0; i < DIM; i++) {
                for (int j = 0; j < DIM; j++) {
                    for (int k = 0; k < DIM; k++) {
                        R.m[i][j] = sum_mod(R.m[i][j], product_mod(A.m[i][k], B.m[k][j]));
                    }
                }
            }
            return R;
        }
    }

    static int sum_mod(int a, int b) {
        int s = a + b;
        if (s >= MOD) s -= MOD;
        return s;
    }

    static int product_mod(int a, int b) {
        return (int)((long)a * b % MOD);
    }

    static int k;
    static Matrix[] f = new Matrix[MAX_D];

    static Matrix generate_matrix(int n, int offset) {
        Matrix M = new Matrix();
        for (int i = 0; i <= k; i++) {
            for (int j = 0; j <= k; j++) {
                int ni = (i == k) ? i : (i + offset) % k;
                int nj = (j == k) ? j : (j + offset) % k;
                M.m[ni][nj] = f[n].m[i][j];
            }
        }
        return M;
    }

    static int compute_sum_of_digits(long n) {
        int sum = 0;
        while (n > 0) {
            sum += n % k;
            n /= k;
        }
        return sum % k;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        long n = sc.nextLong();
        int base = sc.nextInt();
        k = base;

        int digit_count = 0;
        long temp = n;
        while (temp > 0) {
            temp /= k;
            digit_count++;
        }

        Matrix identity = new Matrix();
        for (int i = 0; i <= k; i++) {
            identity.m[i][i] = 1;
        }

        f[0] = identity;
        for (int i = 0; i <= k; i++) {
            f[0].m[i][0] = 1;
        }

        for (int i = 1; i < digit_count; i++) {
            f[i] = identity;
            for (int j = 0; j < k; j++) {
                f[i] = Matrix.multiply(f[i], generate_matrix(i - 1, j));
            }
        }

        long current = 0;
        long power = 1;

        int remaining_digits = digit_count - 1;
        for (int i = 0; i < remaining_digits; i++) {
            power *= k;
        }

        Matrix result = new Matrix();
        for (int i = 0; i <= k; i++) {
            result.m[i][i] = 1;
        }

        while (current < n) {
            // assert(remaining_digits >= 0); // Not needed in Java
            while (current + power <= n) {
                result = Matrix.multiply(result, generate_matrix(remaining_digits, compute_sum_of_digits(current)));
                current += power;
            }
            power /= k;
            remaining_digits--;
        }

        int total_sum = 0;
        for (int i = 0; i <= k; i++) {
            total_sum = sum_mod(total_sum, result.m[k][i]);
        }
        System.out.println(total_sum);
        sc.close();
    }
}
